{"explanation":"For a quadratic, the discriminant Δ = b² − 4ac determines how many times its graph meets the x-axis: twice if Δ > 0, once if Δ = 0, and not at all if Δ < 0. Move the slider through c = 1 to see all three cases for x² − 2x + c = 0.","manimCode":"const title = new Text({ text: 'The discriminant and real roots', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.25, 0]);

const ax = new Axes({ xRange: [-0.5, 2.5, 0.5], yRange: [-1.5, 3, 0.5], xLength: 7, yLength: 4.5, tips: false });
ax.moveTo([-2, -0.5, 0]);

const equation = new MathTex({ latex: 'x^2-2x+c=0' });
await equation.waitForRender();
equation.moveTo([3.7, 1.8, 0]);

const formula = new MathTex({ latex: '\\Delta=b^2-4ac=4-4c' });
await formula.waitForRender();
formula.moveTo([3.7, 0.95, 0]);

let c = 0;
let curve = ax.plot(x => x*x - 2*x + c, { color: BLUE, xRange: [-0.5, 2.5] });
let vertex = new Dot({ point: ax.c2p(1, c - 1), color: YELLOW });
let roots = [];
let status;

function redraw() {
  scene.remove(curve, vertex);
  for (const dot of roots) scene.remove(dot);
  if (status) scene.remove(status);

  curve = ax.plot(x => x*x - 2*x + c, { color: BLUE, xRange: [-0.5, 2.5] });
  vertex = new Dot({ point: ax.c2p(1, c - 1), color: YELLOW });
  scene.add(curve, vertex);

  const delta = 4 - 4*c;
  let message;
  let caseColor;
  if (delta > 0.000001) {
    const offset = Math.sqrt(1 - c);
    roots = [
      new Dot({ point: ax.c2p(1 - offset, 0), color: GREEN }),
      new Dot({ point: ax.c2p(1 + offset, 0), color: GREEN })
    ];
    message = 'Δ = ' + delta.toFixed(2) + ' > 0: two real roots';
    caseColor = GREEN;
  } else if (delta < -0.000001) {
    roots = [];
    message = 'Δ = ' + delta.toFixed(2) + ' < 0: no real roots';
    caseColor = RED;
  } else {
    roots = [new Dot({ point: ax.c2p(1, 0), color: GOLD })];
    message = 'Δ = 0: one repeated root';
    caseColor = GOLD;
  }
  for (const dot of roots) scene.add(dot);
  status = new Text({ text: message, color: caseColor, fontSize: 25 });
  status.moveTo([3.7, 0, 0]);
  scene.add(status);
}

await scene.play(new Write(title));
await scene.play(new Create(ax));
await scene.play(new AnimationGroup([new Write(equation), new Write(formula)]));
redraw();

const controls = new Controls(scene, { position: 'bottom-right', width: 290 });
controls.addSlider({ label: 'c', min: -0.5, max: 1.5, value: 0, step: 0.05, onChange: value => {
  c = value;
  redraw();
}});

await scene.wait(999999);"}

